function M = unroll_higher_order_topology(intra, inter, T, intra1)

if nargin < 4 
    intra1 = intra; 
end;


ss = length(intra); % slice size
M = sparse(ss*T, ss*T);
[rows,columns,order] = size(inter);
for t1 = 1:T
  b = 1 + (t1 - 1)*ss : t1*ss;
  if t1 == 1
      M(b,b) = intra1;
  else
      M(b,b) = intra;
  end
  for t2 = 1:order
    if t1 + t2 <= T
      M(b,b+t2*ss) = inter(:,:,t2);
    end
  end
end

