  if (myismember(i,cnodes)==1)  %cts nodes no need to be transformed 
    bnt_data(i,:)=data(i,:);
    continue;
  end
  values = data(i,:);
  sort_v = sort(values); 
  v_set = unique(sort_v);  

  for j=1:size(values,2)
    index = binary_search(v_set,values(j));
    if (index==-1)
      fprintf('value not found in tranforming data to bnt format.\\n');   
      return;
    end
    bnt_data(i,j)=index;
  end
  old_values{i}=v_set;

end

