function Xdot = gsp_tft(G,X)



NFFT = G.jtv.NFFT;

if isempty(NFFT)
    NFFT = size(X,2);
end;


normalize = 1/sqrt(NFFT);

switch G.jtv.transform
    case 'dft'
        Xdot = fft(X,NFFT,2)*normalize;
    case 'dct'
        if size(X,3)>1
            Xdot = ipermute(dct(permute(X,[2 1 3]),NFFT),[2 1 3]);
        end
        Xdot = dct(X.',NFFT).';

    otherwise
        error('Unknown transform');
end

