function [Tout, Rout] = ComposeTilt(varargin)

	Num = length(varargin);
	if Num <= 0
		Tout = [0 0 0];
		Rout = eye(3);
	elseif Num == 1
		Tout = varargin{1};
		if nargout >= 2
			Rout = RotmatFromTilt(Tout);
		end
	else
		Rout = RotmatFromTilt(varargin{1});
		for k = 2:Num
			T = varargin{k};
			if numel(T) ~= 3
				warning('Ignoring an invalid rotation parameter!');
				continue;
			end
			Rout = Rout * RotmatFromTilt(T);
		end
		Tout = TiltFromRotmat(Rout);
	end

end

