function W = dispersion(X,L)
    W = 0;
    for l = 1:max(L)
        Xl = X(:,L == l);
        switch options.Dist
            case 'norm'
                D = bsxfun(@minus,permute(Xl,[2 3 1]),permute(Xl,[3 2 1]));
                W = W+(D(:)'*D(:))/(2*size(Xl,2));
            case 'angle'
                D = real(acos(real(Xl'*Xl)));
                W = W+sum(D(:))/(2*size(Xl,2));
        end
    end
end

end

