function Wnorm=normalizePSF(W)
sw=size(W);
if numel(sw)<3 %if ncomp=1... 
    sw(3) = 1;
end
Wr=reshape(W, sw(1)*sw(2),sw(3));
q=squeeze(sum(Wr,1));
