    alpha = 1; %no forgetting factor
end

U = {};
for n = 1:N
    switch class(Xnew)
        case {'tensor'} %dense
            XM = double(tenmat(Xnew,n));
        case {'sptensor'} %sparse
            XM = double(sptenmat(Xnew,n));
    end
    Cnew{n} = alpha*C{n} + XM*XM';
    opts.disp = 0;
    opts.issym = 1;
    [U{n}, D] = eigs(Cnew{n},R(n),'LM',opts);    
end

