function pdf2eps(source, dest)
    options = ['-q -paper match -eps -level2 "' source '" "' dest '"'];

    [status, message] = pdftops(options);

    if status
        if isempty(message)
            error('Unable to generate eps. Check destination directory is writable.');
        else
            error(message);
        end
    end

    fid = fopen(dest, 'r+');
    if fid == -1
        return
    end
    fgetl(fid); % Get the first line
    str = fgetl(fid); % Get the second line
    if strcmp(str(1:min(13, end)), '% Produced by')
        fseek(fid, -numel(str)-1, 'cof');
        fwrite(fid, '%'); % Turn ' ' into '%'
    end
    fclose(fid);
end

function [G, cliques, fill_ins] = triangulate(G, order)

MG = G;
n = length(G);
eliminated = zeros(1,n);
cliques = {};
for i=1:n
  u = order(i);
  U = find(~eliminated); % uneliminated
  nodes = myintersect(neighbors(G,u), U); % look up neighbors in the partially filled-in graph
  nodes = myunion(nodes, u); % the clique will always contain at least u
  G(nodes,nodes) = 1; % make them all connected to each other
  G = setdiag(G,0);  
  eliminated(u) = 1;

  exclude = 0;
  for c=1:length(cliques)
    if mysubset(nodes,cliques{c}) % not maximal
      exclude = 1;
      break;
    end
  end

