function s = ComputeSaliency(img, sigma, alpha)

    if (1 ~= size(img, 3)),
        error('The input image should be GRAY.');
    end

    [dx, dy] = GradientMethod(double(img), 'zhou'); 
    grad = dx +1j*dy;

    [~, cc] = EigDecBlock(grad, sigma);
    wt = sqrt((sqrt(cc(1,:,:))+sqrt(cc(2,:,:))).^2 + alpha*(sqrt(cc(1,:,:))-sqrt(cc(2,:,:))).^2);
    s = squeeze(wt);
end



