    return;
end

data = double(data) * scale;
scale = 1;
maxV = max(data(:));

switch lower(type)
    case 'double'
    case 'uint8'         
        scale = maxV / (2^8 - 1);
        data = uint8(data / scale);
    case 'uint16'
        scale = maxV / (2^16 - 1);        
        data = uint16(data / scale);
    case 'uint32'
        scale = maxV / (2^32 - 1);        
        data = uint32(data / scale);
    otherwise
        warning('No conversion occured.  Bad datatype requested.')

