function ans = counting_sort(arr, k)

  ans = zeros(size(arr)); % result array (sorted array)


  C = zeros(1,k); % array for counting

  for i = 1 : length(arr)
    C(arr(i)) += 1;
  endfor

  for j = 2 : k
    C(j) += C(j-1);
  endfor

  for m = length(arr) : -1 : 1
    ans( C( arr(m) ) ) = arr(m);
    C(arr(m)) -= 1;
  endfor

endfunction

