function Y = spm_pp_gen(P,M,U)


Y     = zeros(size(U,1),1);
for i = 1:size(U,1)

    j    = find(U(:,2) == 1);                  % indices for this condition

    b    = P.b;                                % bias
    s    = exp(P.s);                           % sensitivity

    Y(j) = spm_phi((U(j,1) - b)*s);            % logistic function

    j    = find(U(:,2) == 2);

    if M.pC.dbi                                % if no constraint
        b = b + exp(P.dbi);                    % increase bias
    end
    if M.pC.dbd
        b = b - exp(P.dbd);

