function [xOpt,xCost]=convexQuadProgEqConst(Q,b,D,d,algorithm)

if(nargin<5||isempty(algorithm))
    algorithm=-1;
end

if(nargin<3||isempty(D))
    xOpt=-Q\\b;
else
    switch(algorithm)
        case -1
            DQInv=D/Q;
            lambda=-(DQInv*D')\\(d+DQInv*b);
            xOpt=-Q\\(b+D'*lambda);
        otherwise
            A=chol(Q,'upper');
            bLS=-linsolve(A',b);
            xOpt=constrainedLSEq(A,bLS,D,d,algorithm);
    end
end

if(nargout>1)
    xCost=xOpt'*Q*xOpt+2*b'*xOpt;
end
end

