c     = 2.99792458 * 1e8;  % Speed of light
e0    = 1 / (mu0*c^2);     % Permittivity of Free Space

for i=1:Npoles
  monopole = monpos((1:3) + 3*(i-1));

  r = elc - ones(Nelc,1) * monopole;
  r = sqrt(sum(r.^2,2));

  lf(:,i) = 1 ./ (4*pi*cond*r);
end

