function res = indsample(this, t)


res = NaN(1,length(t));
if this.Nsamples > 0
    T = time(this);
    for i = 1:length(t)
        if isfinite(t(i))
            [m,res(i)] = min(abs(T-t(i)));
            if m > (1/this.Fsample)
                warning('Could not find an index matching the requested time %d sec', t(i));
                res(i) = NaN;
            end
        elseif ~isnan(t(i)) % This allows to specify the time window as [-Inf Inf]
            if t(i) < 0
                res(i) = 1;
            else
                res(i) = this.Nsamples;
            end
        end
    end
end

