    maxIter = 50;
    tol = 1e-6;

    w = ones(size(y));

    A = zeros(length(x), deg+1);
    for j = 0:deg
        A(:,j+1) = x.^j;
    end

    for iter = 1:maxIter
        W = diag(sqrt(w));
        params = (W * A) \\ (W * y);

        r = y - A * params;

        w_new = 1 ./ (1 + (abs(r)/k).^2);

        if norm(w - w_new, inf) < tol
            break;
        end

        w = w_new;
    end

    A_out = zeros(length(x_out), deg+1);
    for j = 0:deg
        A_out(:,j+1) = x_out.^j;

