      grad.coilpos(coil,:) = header_info.ch(i).position(j).r_s;
      grad.coilori(coil,:) = header_info.ch(i).position(j).u_s;
      grad.tra(chan,coil) = header_info.ch(i).wgt(j);
    end    
  else
  end
end

