  if ~(f(a) < 0)
    disp("f(a) must be less than 0")
  elseif ~(f(b) > 0)
    disp("f(b) must be greater than zero")
  else 
    c = 100000;
    while abs(f(c)) > error
      c = -f(b) * (b - a) / (f(b) - f(a)) + b;
      if f(c) < 0
        a = c;
      else
        b = c;
      endif
      disp(f(c))
    endwhile
    x = ["The root is approximately located at ", num2str(c)];
