function I = dark_attack(vol, max_pixels, threshold, noise_disturbance)

    ct = 0; % keep track of pixels modified
    flag = 0; % determine when to stop modifying pixels
    vol = single(vol);
    at_vol = vol;

    for i=1:size(vol,1)
        for j=1:size(vol,2)
            for k=1:size(vol,3)
                if vol(i,j,k) > threshold
                    at_vol(i,j,k) = 0;
                    ct = ct + 1;
                    if ct >= max_pixels
                        flag = 1;
                        break;
                    end
