    lap_type = 'combinatorial';
end

n = size(W,1);

d = sum(W,2);
switch lap_type
    case 'combinatorial'
        L = diag(d)-W;
    case 'normalized'
        if issparse(W)
            Dn = diag(d.^(-0.5));
            L = speye(n) - Dn * W * Dn;
        else
            ind = d>0;
            L = - W;
            L(ind, :) = bsxfun(@times, L(ind, :), 1./sqrt(d(ind)));
            L(:, ind) = bsxfun(@times, L(:, ind), 1./sqrt(d(ind))');
            L(1:n+1:end) = 1;
        end
    case 'randomwalk'
        L = speye(n) - diag(d.^(-1))*W;

    case 'none'
        L = sparse(0);
    otherwise
        error(' Unknown laplacian type')
end

