    mu = mtrue.mu;
    T0 = prior.Sigma;
    v0 = prior.dof;
    vn = v0 + n;
    xbar = mean(data);
    data = data - xbar;
    XX = data'*data/n;
    if n > 0
        Tn = T0 + n*XX + n*(xbar-mu)*(xbar-mu)';
    else
        Tn = T0;
    end
    post.dof   = vn;
    post.Sigma = Tn;
    figure(fig1);
    xs = 0.1:0.1:15;
