D=length(X(1,:));
K=length(Lh(1,:));
M=length(Pi);

if (abs(sum(Pi)-1) > 1e-6) 
  disp('ERROR: Pi should sum to 1');
  return;
elseif ((size(Lh) ~= [D*M K]) | (size(Ph) ~= [D 1]) | (size(Mu) ~= [M D]) ...
  | (size(Pi) ~= [M 1] & size(Pi) ~= [1 M]))   
  disp('ERROR in input matrix sizes');
