function [c1,c2] = heuristicXover(p1,p2,bounds,Ops)


retry=Ops(3); 				% Number of retries
i=0;
good=0;
b1=bounds(:,1)';
b2=bounds(:,2)';
numVar = size(p1,2)-1;
if(p1(numVar+1) > p2(numVar+1))
  bt = p1; 
  wt = p2;
else
  bt = p2;
  wt = p1;
end
while i<retry
  a = rand;
  c1 = a * (bt - wt) + bt;

  if (c1(1:numVar) <= b2 & (c1(1:numVar) >= b1))
    i = retry;
    good=1;
  else
    i = i + 1;
  end
end

if(~good) 
  c1 = wt;
end

c2 = bt;

