    hold on
    hd = plot(X,Y,'--');
    set(hd,'Color', cfg.cmapneurons(iUnit,:));
    hold on
  end
  mnmax = [nanmin(dataY(:) - err(:)) nanmax(dataY(:) + err(:))];
end

ylim = mnmax;
d    = ylim(2)-ylim(1);
yl = ylim(1)-0.05*d;
