function [day,month]=dateOfEaster(year)

G=mod(year,19)+1;

C=floor(year/100)+1;

X=floor(3*C/4)-12;
Z=floor((8*C+5)/25)-5;

D=floor(5*year/4)-X-10;

E=mod(11*G+20+Z-X,30);
if(E==25&&G>1||E==24)
    E=E+1;
end

N=44-E;
if(N<21)
   N=N+30;
end

N=N+7-mod(D+N,7);

if(N>31)
    day=N-31;
    month=4;
else
    day=N;
    month=3;
end

end

