     pblk = blk(p,:);
     len = size(A(p),2); 
     for k = 1:len
        if ~isempty(A{p,k})
           iscmp(p,k) = 1-isreal(A{p,k}); 
        end
     end
     iscmp(p,m+1) = 1-isreal(C{p});
