        cvx___.problems(end).checkpoint(4) = x(1+(x(1)==1)) - 1;
    end
end
if nargout
    if nargin == 3 && need_dual
        zD = sparse( mO + 1 : mO + mN, 1 : mN, 1 );
        if ~isr, zD = zD(:,1:2:end) + 1j * zD(:,2:2:end); end

end
