switch method
  case 'L1MBold'
    penalty = log(Ncases)/2; % BIC
    clamped = false(Ncases, Nnodes);
    [model.L1MB_AND, model.L1MB_OR] = L1MB(X01, penalty, discrete, clamped, nodeNames, verbose);
    model.G = model.L1MB_OR;

