function kernel = fix_conv_kernel(weight)
    kernel = zeros(flip(size(weight)));

    weight_size = size(weight);

    buffer = zeros(weight_size(3), weight_size(4));

    for i = 1:weight_size(1)
        for j = 1:weight_size(2)
            buffer(:,:) = weight(i,j,:,:);

            kernel(:,:,j,i) = buffer;
        end
    end
end

