function q = qinterp(Q1, Q2, r)


	q1 = double(Q1);
	q2 = double(Q2);

	if (r<0) | (r>1),
		error('R out of range');
	end

	theta = acos(q1*q2');
	q = {};
	count = 1;

	if length(r) == 1,
		q = quaternion( (sin((1-r)*theta) * q1 + sin(r*theta) * q2) / sin(theta) );
	else
		for R=r(:)',
			qq = quaternion( (sin((1-R)*theta) * q1 + sin(R*theta) * q2) / sin(theta) );
			q{count} = qq;
			count = count + 1;
		end
	end

