        if strcmp(interp_mode,'gaussian')
            w = exp( -dist.^2 / (2*sigma^2) );
        elseif strcmp(interp_mode,'nearest')
            [tmp,I] = min(dist);
            w = dist*0; w(I) = 1;
        else
            if isfield(options, 'exponent')
