            t = tic;
            obj.problem.solve( dt );
            ctime = toc( t );

            obj.simulation_time = dt;
            obj.solver_count = 1;
            obj.computation_time = ctime;
        end

        function time = get_simulation_time( obj )
            time = obj.simulation_time;
