function [L,S] = PCP(M,lam,tol)



beta = .25/mean(abs(M(:))); % 
maxit = 1000;

[m,n] = size(M);
S = zeros(m,n);
L = zeros(m,n);
Lambda = zeros(m,n); % the dual variable

for iter = 1:maxit

    nrmLS = norm([S,L],'fro');

    X = Lambda / beta + M;
    Y = X - L;
    dS = S;
    S = sign(Y) .* max(abs(Y) - lam/beta, 0); % softshinkage operator
    dS = S - dS;

    Y = X - S;
    dL = L;

    [U,D,V] = svdecon(Y); % fastest

    VT=V';
    D = diag(D);
    ind = find(D > 1/beta);
    D = diag(D(ind) - 1/beta);
    L = U(:,ind) * D * VT(ind,:);
    dL = L - dL;

    RelChg = norm([dS,dL],'fro') / (1 + nrmLS);
    if RelChg < tol, break; end

    Lambda = Lambda - beta * (S + L - M);
end
end

