        pclass(~nas) = pclass2;
        result = pclass;
    end
else
    maxdist = x(:,1);
    pclass = ones(d(1),1);
    for i = 2:d(2)
        l = x(:,i)>maxdist;
        pclass(l) = i;
        maxdist(l) = x(l,i);
    end
    result = pclass;
end

