methods (Access = private)

    function init(obj,cParams)
        obj.shapeFunctions = cParams.shapeFunctions;
        obj.weights        = cParams.weights;
    end

    function [jV, djV] = computeValueAndGradient(obj, x, compFunc)
        nF  = length(obj.shapeFunctions);
        bDa  = length(obj.shapeFunctions);
        Jc  = cell(nF,1);
        dJc = cell(nF,1);
        for iF = 1:nF
            shI = obj.shapeFunctions{iF};
            if nargout(compFunc) == 2
                [j,dJ]  = compFunc(shI,x);
                bDa(iF) = false;
            else
                [j,dJ,bD]  = compFunc(shI,x,obj.moveBatch);
                bDa(iF) = bD;
            end
            Jc{iF}  = j;
            dJc{iF} = obj.mergeGradient(dJ);
        end

        jV  = 0;
        djV = zeros(size(dJc{1}));
        for iF = 1:nF
            wI  = obj.weights(iF);
            jV  = jV  + wI*Jc{iF};
            djV = djV + wI*dJc{iF};
        end

        obj.isBatchDepleted = any(bDa);
        obj.shapeValues = Jc;

function [O,lo] = update_order_greedy(A)
    K = size(A,2);
    if ~(size(A,1) == K)
        A = A'*A;
    end

    A = A>0;
    A(1:K+1:K^2) = 0;

    O{1} = 1;
    lo(1) = 1;
    for i = 2:K
       cont = true;
       for j = 1:length(O)           
           if ~any(A(i,O{j}))
               O{j} = [O{j},i];
               lo(j) = lo(j) + 1;
               cont = false;
               break;
           end           
       end
       if cont
           O{length(O)+1} = j;
           lo = [lo,1];
       end
    end    
end

