function x = cwt_iw(Wx, type, opt)
    if nargin<3, opt = struct(); end

    [na, n] = size(Wx);

    [N,n1,n2] = p2up(n);
    Wxp = zeros(na, N);

    Wxp(:, n1+1:n1+n) = Wx;
    Wx = Wxp; clear Wxp;

    noct = log2(N)-1;
    nv = na/noct;
    as = 2^(1/nv) .^ (1:1:na);

    assert(mod(noct,1) == 0);
    assert(nv>0 && mod(nv,1)==0); % integer

    Cpsi = cwt_adm(type, opt);

    x = zeros(1, N);
    for ai=1:na
        a = as(ai);
        Wxa = Wx(ai, :);

        psih = wfilth(type, N, a, opt);

        Wxah = fft(Wxa);
        xah = Wxah .* psih;
        xa = ifftshift(ifft(xah));

        x = x + xa/a;
    end

     x = log(2^(1/nv))/Cpsi * real(x);

     x = x(n1+1: n1+n);

end % cwt_iw

