function [x_tplus1,z_tplus1,pseudo_data] = DAMP_oneIter(y,z_t,x_t,width,height,denoiser,M_func,Mt_func)

if nargin==8%function
    M=@(x) M_func(x);
    Mt=@(z) Mt_func(z);
else%Matrix
    M=@(x)M_func*x;
    Mt=@(z)M_func'*z;
end
denoi=@(noisy,sigma_hat) denoise(noisy,sigma_hat,width,height,denoiser);

n=width*height;
m=length(y);

pseudo_data=Mt(z_t)+x_t;
sigma_hat=sqrt(1/m*sum(abs(z_t).^2));
x_tplus1=denoi(pseudo_data,sigma_hat);
eta=randn(1,n);
epsilon=max(pseudo_data)/1000+eps;
div=eta*((denoi(pseudo_data+epsilon*eta',sigma_hat)-x_tplus1)/epsilon);
z_tplus1=y-M(x_tplus1)+1/m.*z_t.*div;
end

function [node, elem] = meshresample(v, f, keepratio)

[node, elem] = domeshsimplify(v, f, keepratio);

if (length(node) == 0)
    warning(['Your input mesh contains topological defects, and the ', ...
             'mesh resampling utility aborted during processing. Now iso2mesh ', ...
             'is trying to repair your mesh with meshcheckrepair. ', ...
             'You can also call this manually before passing your mesh to meshresample.']);
    [vnew, fnew] = meshcheckrepair(v, f);
    [node, elem] = domeshsimplify(vnew, fnew, keepratio);
end
[node, I, J] = unique(node, 'rows');
elem = J(elem);
saveoff(node, elem, mwpath('post_remesh.off'));

end

