function mask = flatsegment(node, edge)

idx = edge;
nn = length(idx);
val = zeros(nn, 1);
for i = 1:nn
    tet = mod(i:i + 3, nn);
    tet(find(tet == 0)) = nn;
    val(i) = (abs(det([node(idx(tet), :), ones(4, 1)])) > 1e-5);
end

val(end + 1:end + 2) = val(1:2);
mask = {};
oldend = 1;
for i = 1:nn
    if (val(i) == 1 & val(i + 1) == 1 & val(i + 2) == 0)
        val(i + 2) = 2;
        mask{count} = idx(oldend:i + 2);
        count = count + 1;
        oldend = i + 2;
    else
        mask{count} = [idx(oldend:end); mask{1}];
        break
    end
end

