function [label, model, energy] = knKmeans(X, init, kn)
K = kn(X,X);
n = size(K,2);
if numel(init)==1
    k = init;
    label = ceil(k*rand(1,n));
elseif numel(init)==n
    label = init;
end
last = zeros(1,n);
while any(label ~= last)
    [~,~,last(:)] = unique(label);   % remove empty clusters
    E = sparse(last,1:n,1);
    E = E./sum(E,2);
    T = E*K;
    [val, label] = max(T-dot(T,E,2)/2,[],1);
end
energy = trace(K)-2*sum(val); 
model.kn = kn;
model.label = label;
model.X = X;

function [c, ceq] = ConstraintFCN(u,uold,x,Ts,N,LBo,UBo,LBdu,UBdu,p)

zMin = LBo;
zMax = UBo;

c = zeros(2*N,1); 
cy = zeros(2*N,1);

xk = x;
uk = u(1);
duk = u(1)-uold;
for ct=1:N
    xk1 = rk4u(@F8Sys,xk,uk,Ts,1,[],p);

    cy(2*ct-1) = -xk1(1)+zMin; 
    c(2*ct-1) = -duk+LBdu; 

    cy(2*ct) = xk1(1)-zMax;
    c(2*ct) = duk-UBdu;

    xk = xk1;
    if ct<N
        uk = u(ct+1);
        duk = u(ct+1)-u(ct);
    end
end

