       end
    end
    logEigsMatrix = log( eigsMatrix );
    distsMatrix = real( sqrt( sum(logEigsMatrix.^2, 4 ) ) );

    likelihoodsMatrix = sum( distsMatrix, 3 ) - max( distsMatrix, [], 3 );

end


