    for n = 1:length(ind)
      if typeAsym(n) > 0
        for nn = 1:length(ind)
          if sum(abs(rAsym(nn,:)-fliplr(rAsym(n,:)))) < 10^(-2)
            typeAsym(nn) = -1;
          end
        end
      end
    end
    typeAsym = typeAsym(typeAsym >= 0);
    type = [typeSym; typeAsym];
    stab = type >= 3;
    if isempty(type)
      STABTYPE(nc,nw) = -1;
    elseif sum(stab) < 2
      STABTYPE(nc,nw) = max(type); % show stable type if any
    elseif sum(stab) == 2
      STABTYPE(nc,nw) = 5;
    else
      error('Three or more stable fixed points?')
    end
  end
end
