      j=j+1;
    end
    N_babies(1,j)=N_babies(1,j)+1;
  end;
end;

index=1;
for i=1:S
  if (N_babies(1,i)>0)
    for j=index:index+N_babies(1,i)-1
      outIndex(j) = inIndex(i);
    end;
  end;   
  index= index+N_babies(1,i);   
end

