	k(i) = Concentration(angles(group==i));
end
kappa = median(k);

for i = 1:r,
	mu(i) = circ_mean(angles(group==i));
end

if kappa >= 1,
	fr = ComputeStatistics(angles,group,mu);
	p = 1 - fcdf(fr,r-1,N-r);
	p = 2 * min(p, 1-p);
else
	for i = 1:r,
		angles(group==i) = angles(group==i)-mu(i);
	end
	fr = ComputeStatistics(angles,group,mu);
	for i = 1:nRandomizations,
		x = randperm(N);
		group = group(x);
		for j = 1:r,
			mu(j) = circ_mean(angles(group==j));
		end
		fr_rand(i) = ComputeStatistics(angles,group,mu);
	end

