        if step == 0    %% if it's a "repeat" step (e.g. after bus type changes)
            evnts.eidx = eidx;
            evnts.name = cpf_events(eidx).name;
            evnts.zero = 1;
            evnts.idx = idx;
            evnts.step_scale = 1;

