params.maxit = 50000;
params.step_size = .9;
params.verbosity = 1;
W = gsp_learn_graph_log_degrees(Z, .031, .003, params);

if not(all(diag(W) == 0))
    n_errors = n_errors + 1;
end

if not(all(W(:) >= -tol))
    n_errors = n_errors + 1;
end

if not(all(sum(W) >= tol * max(sum(W))))
    n_errors = n_errors + 1;
end


end

