function [U,isPosDef] = cholproj(A)

U = zeros(size(A));
isPosDef = 1;
for i = 1:cols(A)
  for j = i:rows(A)
    k = 1:(i-1);
    s = A(i,j) - U(k,i)'*U(k,j);
    if i == j
      if s <= 0
	isPosDef = 0;
	U(i,i) = 0;
      else
	U(i,i) = sqrt(s);
      end
    else
      if U(i,i) > 0
	U(i,j) = s / U(i,i);
      else
	U(i,j) = 0;
      end
    end
  end
end

