        internal.stats.parseArgs(pnames,dflts,varargin{:});

for i = 1:max_iter

    if bUpdateZ
        Z = X * pinv(H);
    end

    A = Z' * X;
    Ap = (abs(A)+A)./2;
    An = (abs(A)-A)./2;

    B = Z' * Z;
    Bp = (abs(B)+B)./2;
    Bn = (abs(B)-B)./2;

    if bUpdateH
        H = H .* sqrt((Ap + Bn * H) ./ (An + Bp * H + eps));
    end

    if mod(i, 10) == 0 || mod(i+1, 10) == 0 

        s = X - Z * H;
        dnorm = sqrt(sum(s(:).^2));

        if mod(i+1, 10) == 0
            dnorm0 = dnorm;
            continue
        end

        if mod(i, 100) == 0 && verbose
            display(sprintf('...Semi-NMF iteration #%d out of %d, error: %f\\n', i, max_iter, dnorm));

