function ses = calculate_ses(cp,lb,car)

    lb_pc = [0; diff(lb) ./ lb(1:end-1)];
    eq_pc = [0; diff(cp) ./ cp(1:end-1)];

    ses = (car .* lb .* (1 + lb_pc)) - ((1 - car) .* cp .* (1 + eq_pc));
    ses(ses < 0) = 0;

end

