function [w] = bohmanwin(L)
  if (nargin < 1)
    help(mfilename)
  elseif(~ isscalar(L))
    error('L must be a number');
  elseif(L < 0)
    error('L must be positive');
  end

  if(L ~= floor(L))
    L = round(L);
    warning('L rounded to the nearest integer.');
  end

  if(L == 0)
    w = [];

  elseif(L == 1)
    w = 1;

  else
    N = L-1;
    n = -N/2:N/2;

    w = (1-2.*abs(n)./N).*cos(2.*pi.*abs(n)./N) + (1./pi).*sin(2.*pi.*abs(n)./N);
    w(1) = 0;
    w(length(w))=0;
    w = w';
  end
end

function detection = detectAtMultipleScales(im, w, hogCellSize, scales)

modelWidth = size(w, 2) ;
modelHeight = size(w, 1) ;
bestScore = -inf ;
minScore = +inf ;
maxScore = -inf ;
h = [] ;

for s = scales
  t = imresize(im, 1/s) ;

  hog = vl_hog(t, hogCellSize) ;

  scores = vl_nnconv(hog, w, []) ;

  [score, index] = max(scores(:)) ;
  if score > bestScore
    bestScore = score ;
    [hy, hx] = ind2sub(size(scores), index) ;
    x = (hx - 1) * hogCellSize * s + 1 ;
    y = (hy - 1) * hogCellSize * s + 1 ;
    detection = [
      x - 0.5 ;
      y - 0.5 ;
      x + hogCellSize * modelWidth * s - 0.5 ;
      y + hogCellSize * modelHeight * s - 0.5 ;] ;
  end

  vl_tightsubplot(numel(scales),find(s==scales)) ;
  imagesc(scores) ; axis off square ;
  h(end+1) = gca;
  minScore = min([minScore;scores(:)]) ;
  maxScore = max([maxScore;scores(:)]) ;
end

set(h, 'clim', [minScore, maxScore]) ;

