function [ sf ] = freplaceprintf( s )
sf=s;
I=regexp(s,'[sf]+printf\\(');
if ~isempty(I) 
    ip=I(1);% NOTE:only deals with one printf..
    if s(ip)=='s'
        scmd='sprintf';
    elseif s(ip)=='f'
        scmd='fprintf';
    else
        scmd='printf';
    end 
    [~,p1,p2]=ffindmatching(s,ip+3,'(',')',1);
    s=strrep(s,'\\','\\\\');
    s=strrep(s,'%','%%');

    s_print=s((p1+1):(p2-1)); % not safe and will keep the %
    s_assign=s(1:(ip-1)); 
    s_post=s((p2+1):end); 
    sf=['!m2f: ' s '\\n '] ;
    switch(scmd)
