function W = maskAttentionWeights(W,nvp)

arguments
    W
    nvp.CausalMask (1,1) logical = true
    nvp.InputMask = []
end

if nvp.CausalMask
    numAllSubwords = size(W,1);
    numInputSubwords = size(W,2);
    numPreviousSubwords = numInputSubwords-numAllSubwords;

    mask = triu( ...
        ones([numAllSubwords numInputSubwords],'like', extractdata(W)), ...
        numPreviousSubwords );

    W = W.*mask - (1e10)*(1-mask);
end

if ~isempty(nvp.InputMask)
    mask = permute(nvp.InputMask,[2,1,4,3]);
    mask = repmat(mask,[1,size(W,2),size(W,3),1]);
    W = W-1e4.*(~mask);
end
end

function order = topological_sort(A)

n = length(A);
indeg = zeros(1,n);
zero_indeg = []; % a stack of nodes with no parents
for i=1:n
  indeg(i) = length(parents(A,i));
  if indeg(i)==0
    zero_indeg = [i zero_indeg];
  end
end

t=1;
order = zeros(1,n);
while ~isempty(zero_indeg)
  v = zero_indeg(1); % pop v
  zero_indeg = zero_indeg(2:end);
  order(t) = v;
  t = t + 1;
  cs = children(A, v);
  for j=1:length(cs)
    c = cs(j);
    indeg(c) = indeg(c) - 1;
    if indeg(c) == 0
      zero_indeg = [c zero_indeg]; % push c 
    end
  end
end

