function [order, chordal, cliques, numpa] = maxCardinalitySearch(G, initNode)



if nargin < 2, initNode = 1; end
G     = logical(G); 
G     = setdiag(G, true); % for chordality checking
d     = size(G, 1); 
order = zeros(1, d); 
numbered    = false(1, d); 
order(1)    = initNode; 
numbered(initNode) = true; 
chordal = true;
C = cell(1,d);
numpa = zeros(1,d);
C{1} = initNode; % KPM 27Sep10
for i=2:d
  score = -1*ones(1,d); % disconnected nodes get 0, so others should be -1
  U = find(~numbered);% unnumbered verticies
  for j=1:numel(U)
    k = U(j); u = k;
    score(u) = sum((G(k, :) | G(:, k)') & numbered); 
  end
  u = maxidx(score);
  order(i) = u;
  numbered(u) = true;

  pa = intersectPMTK(neighbors(G,u), order(1:i-1));
  if ~isequal(G(pa,pa), ones(length(pa)))
    chordal = false;
    return;
  end

  C{i} = rowvec(unionPMTK(pa, u)); % [pa u]; % ensure sorted
  numpa(i) = length(pa);
end

isLadder = false(1,d);
for i=1:(d-1)
  isLadder(i) = numpa(i) >= numpa(i+1);
end
isLadder(d) = true;

L = 1;             % Length of the rod
T = 1;             % Total time
N = 100;           % Number of spatial grid points
alpha = 0.02;      % Thermal diffusivity constant

for k=1:5
    if k > 1
        N = N*2;
    end

    dx = L/N;
    dt = 0.5*dx*dx/alpha;

    M = int32(T/dt);

    x = linspace(0,L,N+1);

    u = zeros(N+1,M+1);

    u(:,1) = sin(pi*x);

    time = 0.0;
    toatlError(:) = 0;

    for j = 1:M
        for i = 2:N
            u(i,j+1) = u(i,j) + alpha*dt/dx^2 *(u(i+1,j) - 2*u(i,j) + u(i-1,j));
        end

        time = time + dt;
        exact = sin(pi*x)*exp(-alpha*(pi)^2*time);

        Error = exact' - u(:,j);
        totalError(j) = sum(Error);

    end
    E(k) = norm(totalError,inf);
    DX(k) = dx;
end

figure
plot(DX,E,'o-')
xlabel("Delta x")
ylabel("Error")

