function [theta,P,res]=CoSpace_single(Y,X,Z,alfa,beta,L,maxiter)

epsilon = 1e-4; % Tolerance error
iter=1; 
stop = false;
res=zeros(1,maxiter); % Residuals

while ~stop && iter < maxiter+1

        P=(Y*Z')/(Z*Z'+alfa*eye(size(Z*Z'))); 

        theta=Solving_Theta_single(Y,P,Z,X,maxiter);
        Z=theta*X;

     res(1,iter) = 0.5*norm(Y-P*theta*X,'fro')^2 + 0.5*alfa*norm(P,'fro')^2 ;

    if iter>1
       r_Obj=abs(res(1,iter)-res(1,iter-1))/abs(res(1,iter-1));
       if r_Obj<epsilon
            stop = true;
            fprintf(' i = %f,res_Obj= %f\\n',iter,r_Obj);
            break;
       end

       if mod(iter,10) == 1
           fprintf(' i = %f,res_Obj= %f\\n',iter,r_Obj);
       end
    end

    iter=iter+1;
end
end

