function minInd = minimalInOrbit(degree, generators, b, ordering)
    if size(generators, 2) == 0
        minInd = b;
    else
        if nargin < 4
            ordering = 1:degree;
        end
        done = false(1, degree);
        toCheck = b;
        minVal = ordering(b);
        minInd = b;
        done(b) = true;
        while 1
            images = generators(toCheck, :);
            images = images(:);
            toCheck = images(~done(images));
            if isempty(toCheck)
                break
            else
                done(toCheck) = true;
                [minVal1, minInd1] = min(ordering(toCheck));
                if minVal1 < minVal
                    minInd = toCheck(minInd1);
                end
            end
        end
    end

