        for e = 1 : n_el - 1
            id_el = (this.sat.el(:, s) > el_lim(e)) & (this.sat.el(:, s) <= el_lim(e + 1));
            if sum(id_el) > 0
                for id_s = find(go_id == s)'
                    err4el(s, e) = max([err4el(s, e); nan2zero(err(id_el, id_s))]);
                end
            end

