    if numcols(point) ~= numcols(newcost)
        error('number of columns in point must match columns in newcost');
    end
    for i=1:numcols(point)
        X = sub2ind(size(ds.costmap), point(2,i), point(1,i));
        ds.costmap(X) = newcost(i);
    end
    if ds.t(X) == ds.CLOSED
