                catch
                    err_code = 1;
                    Core_Utils.printEx(ex);
                    log = Core.getLogger();
                    log.addWarning(sprintf('Setting of "%s" failed', par_name));
                end
            end
            log = Core.getLogger();
            log.addWarning(sprintf('Trying to set an unrecognized parameter "%s"', par_name));
            err_code = -1;
        else
            try
                this.(par_name) = new_value;
            catch ex
                err_code = 1;
                Core_Utils.printEx(ex);
                log = Core.getLogger();
                log.addWarning(sprintf('Setting of "%s" failed', par_name));
