function [localCPDs, localCPDpointers, localMu, localSigma] = ...
  condGaussCpdMultiFit(X, obs, Nstates)

[Ncases Nnodes Ndims] = size(obs); %#ok
localCPDs = cell(1, Nnodes);
localCPDpointers = 1:Nnodes; % each node has its own CPD

localMu = zeros(Ndims,  Nstates, Nnodes);
localSigma = zeros(Ndims, Ndims, Nstates, Nnodes);

for t=1:Nnodes
  Y = squeeze(obs(:,t,:)); % Y(case,dim)
  Z = canonizeLabels(X(:,t)); %
  if nunique(Z) < Nstates
    sprintf('node %d only has %d states\\n', t, nunique(Z));
  end
  Sigma = zeros(Ndims, Ndims, Nstates);
  mu = zeros(Ndims, Nstates);
  for c=1:Nstates
    ndx = (Z==c);
    mu(:,c) = mean(Y(ndx,:))';
    Sigma(:,:,c) = shrinkcov(Y(ndx,:));
  end
  localCPDs{t} = condGaussCpdCreate(mu,  Sigma);

  localMu(:,:,t) = mu;
  localSigma(:,:,:,t) = Sigma;
end

end

function colormatrix = gradientgen(cmap2use, ncolors)
if ~exist('cmap2use', 'var') || isempty(cmap2use); cmap2use = []; end
if ~exist('ncolors', 'var') || isempty(ncolors); ncolors = []; end
cmaps = {'wr', 'wk', 'wb', 'wg', 'wm', 'wc', 'kr', 'mbg', 'gry'}; % but you can even mix 3 of them
maxc = 180;
if ~isempty(cmap2use)
    if isstr(cmap2use)
        cmap2use = cmap2use;
    else
        cmap2use = cmaps{cmap2use};
    end
    cmap = buildcmap(cmap2use); 
    cmap = cmap(round(76:255), :);
    if cmap2use == 1
        colormatrix = cmap(maxc,:);
    else % resampling
        colormatrix = interp1(1:maxc,cmap,1:maxc/(ncolors+1):maxc);
        colormatrix = colormatrix(1:ncolors,:);
    end
else
    fprintf('Posible colormaps (')
    for i = 1:numel(cmaps); if i ~= numel(cmaps); fprintf([cmaps{i}, ' , ']); else fprintf([cmaps{i}]); end; end
    fprintf(') \\n')
    colormatrix = [];
end

