function r=unbiasedR(xState,SState,RGlob2ENU,rRx,xi,w)

    xi=bsxfun(@plus,SState*xi,xState);

    xiLocal=RGlob2ENU*bsxfun(@minus,xi(1:3,:),rRx);

    rCub=sqrt(sum(xiLocal(1:3,:).^2,1));
    r=sum(bsxfun(@times,rCub(:),w(:)));
end

