slice = uint8((double(slice) - displayRange(1)) * 255 / extent);

if ~isempty(lut)
    if ischar(lut)
        lut = feval(lut, 256);
    end

    lutMax = max(lut(:));
    dim = size(slice);
    rgb = zeros([dim 3], 'uint8');

    for c = 1:size(lut, 2)
        res = zeros(size(slice));
        for i = 0:size(lut,1)-1
            res(slice==i) = lut(i+1, c);
        end
        rgb(:,:,c) = uint8(res * 255 / lutMax);
    end

else
    rgb = repmat(slice, [1 1 3]);
end

