z = pnt(:,3);

l = ones(length(x),1);
O = zeros(length(x),1);

D = [(x.*x + y.*y + z.*z) x y z l];

Dx = [2*x l O O O];
Dy = [2*y O l O O];
Dz = [2*z O O l O];

M = D'*D;
N = Dx'*Dx + Dy'*Dy + Dz'*Dz;

[v, evalues] = eig(M);
evalues = diag(evalues);
Mrank = sum(evalues > eps*5*norm(M));

