  [dmin,dminindex] = max(diag(evalues));
  pvec = v(:,dminindex(1))';
else
  pvec = v(:,evalues <= eps*5*norm(M))';
  [m,n] = size(pvec);
  if m > 1
    pvec = pvec(1,:);
  end
end

