function vectors = em_pca(X, K)
  if (nargin == 0)
    error('em_pca: not enough input arguments');
  elseif (nargin == 1)
    K = 1;
  end % if

  epsilon = 1e-4; % Note that smaller values are highly impractical

  [N, D] = size(X);
  vectors = NaN(D, K, class(X));

  for k = 1:K
    mu = rand(D, 1) - 0.5;
    mu = mu / norm(mu);
    for iter = 1:N
      prev_mu = mu;

      dots = X * mu;
      mu = dots.' * X;
      mu = mu(:) / norm(mu);

      if (sum(abs(mu - prev_mu)) < epsilon)
        break;
      end % if
    end % for

    if (k == 1)
      vectors(:, k) = mu;
    elseif (k < K)
      mu = reorth(vectors(:, 1:k-1), mu, 1);
      mu = mu / norm(mu);
      vectors(:, k) = mu;

      X = X - (X * mu) * mu.';
    else % k == K

