function [c, G, C, d, l, u] = conversionConZonoStarSet(cZ)



m = size(cZ.G, 2);

if isempty(cZ.A)

    c = cZ.c;
    G = cZ.G;
    C = [eye(m); -eye(m)];
    d = ones(2*m, 1);
    u = ones(m, 1);
    l = -ones(m, 1);

else
    p_ = pinv(cZ.A) * cZ.b;

    T = null(cZ.A);

    A = [eye(m); -eye(m)];
    b = ones(2*m, 1);
    C = A * T;
    d = b - A * p_;
    c = cZ.c + cZ.G * p_;
    G = cZ.G * T;
    int = interval(polytope(C, d));
    l = infimum(int);
    u = supremum(int);
end

end

