function W = weight_conversion(W, wcm)



switch wcm
    case 'binarize'
        W=double(W~=0);         % binarize
    case 'normalize'
        W=W./max(abs(W(:)));    % scale by maximal weight
    case 'lengths'
        E=find(W); 
        W(E)=1./W(E);           % invert weights
    case 'autofix'
        n = length(W);
        W(1:n+1:end)=0;

        idx = isnan(W) | isinf(W);
        if any(any(idx));
            W(idx)=0;
        end

        U = unique(W);
        if numel(U)>1
            idx_0 = abs(U)<1e-10;
            idx_1 = abs(U-1)<1e-10;
            if all(idx_0 | idx_1)
                W(idx_0)=0;
                W(idx_1)=1;
            end
        end

        if ~isequal(W,W.');
            if max(max(abs(W-W.'))) < 1e-10;            
                W=(W+W).'/2;
            end
        end
    otherwise
        error('Unknown weight-conversion command.')
end

