function [Lr,S] = stoc_rpca(D, lambda1, lambda2, nrank)
  [ndim, nsample] = size(D);
  L = rand(ndim,nrank);
  A = zeros(nrank,nrank);
  B = zeros(ndim,nrank);
  S = zeros(ndim,nsample);
  Lr = zeros(ndim,nsample);
  for t = 1:nsample
    disp(t);
    z = D(:,t);
    [r,s] = solve_proj2(z,L,lambda1,lambda2);
    S(:,t) = s;
    A = A + r*r';
    B = B + (z-s)*r';
    L = update_col_orpca(L,A,B,lambda1/nsample);
    Lr(:,t) = L * r;
  end
end

