function msg = qerror(msg)


wrec = warning('query', 'backtrace');
if strcmpi(wrec.state, 'on')
  return
end

if ~isempty(msg)
  CR = sprintf('\\n');
  m = sprintf('Error using ==>');
  i = findstr(msg,CR);
  [c{1:length(i)+1,1}] = deal('');
  if isempty(i)
    c{1} = msg;
  else
    c{1} = msg(1:i(1));
    for k=2:length(i)
      c{k} = msg(i(k-1)+1:i(k));
    end
  end
  i = strmatch(m,c);
  if ~isempty(i), [c{i}] = deal(''); end
  msg = [c{:}];
  i = find(msg ~= ' ' & msg ~= 0 & msg ~= CR);
  if ~isempty(i)
    msg = msg(1:max(i));
  end
end

