    xyz2cam = reshape(info.ColorMatrix2,3,3)';
    srgb2xyz = [0.4124564 0.3575761 0.1804375;
        0.2126729 0.7151522 0.0721750;
        0.0193339 0.1191920 0.9503041];
    rgb2cam = xyz2cam * srgb2xyz;
