function T = deriv(ets, q)
    switch ets.type
        case ETS.RX
            T = r2t( skew([1 0 0])*rotx(q) );
        case ETS.RY
            T = r2t( skew([0 1 0])*roty(q) );
        case ETS.RZ
            T = r2t( skew([0 0 1])*rotz(q) );
        case ETS.TX
            T = transl(1, 0, 0);
        case ETS.TY
            T = transl(0, 1, 0);
        case ETS.TZ
            T = transl(0, 0, 1);
    end
    T(4,4) = 0;
end



