function [x,cnt] = pagerankpow(G)



if nargin == 0;
   [x, cnt] = pagerankpow(rand(10) > 0.8);
   return
end

[n,n] = size(G);
for j = 1:n
   L{j} = find(G(:,j)); % set of links coming into node j
   c(j) = length(L{j}); % in-degree
end

p = .85;
delta = (1-p)/n;
x = ones(n,1)/n;
z = zeros(n,1);
cnt = 0;
while max(abs(x-z)) > .0001
   z = x;
   x = zeros(n,1);
   for j = 1:n
      if c(j) == 0
         x = x + z(j)/n;
      else
         x(L{j}) = x(L{j}) + z(j)/c(j);
      end
   end
   x = p*x + delta;
   cnt = cnt+1;
end

end

