function [pl] = plm(x,l,m)
b= (-1)^m * 2^l;
pl =0;
for k = m:l
    val=prod((l+k-1)/2-(0:(l-1)));
    vals2= prod(l-(0:(k-1)));
    c = (factorial(k)/factorial(k-m)) * vals2/factorial(k) * val/factorial(l);
    pl=pl+(b*(1-x.^2).^(m/2))*c.*x.^(k-m);
end
end

