function outPoint = translation2D(inPoint, offsetPoint)
    xt = offsetPoint(1); yt = offsetPoint(2);

    T = affine2d(...
        [...
            1 , 0 , 0; ...
            0 , 1 , 0; ...
            xt, yt, 1  ...
        ]...
    );

    outPoint = transformPointsForward(T, inPoint);
end

function outPoint = rotation2D(inPoint, phi)
    T = affine2d(...
        [...
            cos(phi) , sin(phi), 0; ...
            -sin(phi), cos(phi), 0; ...
            0        , 0       , 1; ...
        ]...
    );

    outPoint = transformPointsForward(T, inPoint);
end



