      continue
    end

    if iscell(data.(input{i}))
      tmp1 = ~cellfun('isempty', data.(input{i}));
      tmp2 = ~cellfun(@(x) all(isnan(x)), data.(input{i}));
      tmp(:, i) = all([tmp1 tmp2], 2);

    else
      tmp2 = data.(input{i});
      tmp2(isnan(tmp2)) = 0;
      tmp(:, i) = logical(tmp2);

    end

  end

  switch lower(transformer.Name)
    case 'and'
      data.(output{1}) = all(tmp, 2);
    case 'or'
      data.(output{1}) = any(tmp, 2);
    case 'not'

      data.(output{1}) = ~tmp;
  end

end
