     ned=dum-1;
    [n,nsd]=size(Coord);
    [n,nd]=size(Dof);
     nend=ned/nen;
    for i = 1:nel
       nodnum=zeros(1,nen);
       for j = 1:nen
          check=Dof(:,1:nend)-ones(n,1)*Edof(i,(j-1)*nend+2:j*nend+1);
          [indx,dum]=find(check==0);
          nodnum(j)=indx(1);
       end
          Ex(i,:)=Coord(nodnum,1)';
       if nsd>1
          Ey(i,:)=Coord(nodnum,2)';
