function [pos] = bancroft(B_pass)



v_light = Core_Utils.V_LIGHT;
Omegae_dot = goGNSS.OMEGAE_DOT_GPS;

pos = zeros(4,1);

for iter = 1:2
    B = B_pass;
    [m,n] = size(B); %#ok<NASGU>
    for i = 1:m
        x = B(i,1);
        y = B(i,2);
        if iter == 1
            traveltime = B(i,4)/v_light;
        else
            z = B(i,3);
            rho = (x-pos(1))^2+(y-pos(2))^2+(z-pos(3))^2;
            traveltime = sqrt(rho)/v_light;
        end
        angle = traveltime*Omegae_dot;
        cosa = cos(angle);
        sina = sin(angle);
        B(i,1) =  cosa*x + sina*y;
        B(i,2) = -sina*x + cosa*y;
    end

    if m > 4
        BBB = (B'*B)\\B';
    else
        BBB = inv(B);
    end
    e = ones(m,1);
    alpha = zeros(m,1);
    for i = 1:m
        alpha(i) = lorentz(B(i,:)',B(i,:)')/2;
    end

    this.obs_full_name = {};
end

