function recurse_copyfile(old, new, fo, fn)
list = dir(old);
for i=1:numel(list)
  if strcmp(list(i).name, '.')
    continue
  elseif strcmp(list(i).name, '..')
    continue
  elseif list(i).isdir
    [p, f, x] = fileparts(list(i).name);
    mkdir(fullfile(new, [f, x]));
    if strcmp(f, fo)
      recurse_copyfile(fullfile(old, [fo, x]), fullfile(new, [fn, x]), fo, fn);

