function M = spherecomplexfactory(n, m)



    if ~exist('m', 'var')
        m = 1;
    end

    if m == 1
        M.name = @() sprintf('Complex sphere S^%d', n-1);
    else
        M.name = @() sprintf('Unit F-norm %dx%d complex matrices', n, m);
    end

    M.dim = @() 2*(n*m)-1;

    M.inner = @(x, d1, d2) real(d1(:)'*d2(:));

    M.norm = @(x, d) norm(d, 'fro');

    M.dist = @(x, y) acos(real(x(:)'*y(:)));

    M.typicaldist = @() pi;

    M.proj = @(x, d) reshape(d(:) - x(:)*(real(x(:)'*d(:))), n, m);

	M.egrad2rgrad = M.proj;

	M.tangent = M.proj;

    M.exp = @exponential;

    M.retr = @retraction;

    M.log = @logarithm;
    function v = logarithm(x1, x2)
        error('The logarithmic map is not yet implemented for this manifold.');
    end

    M.hash = @(x) ['z' hashmd5([real(x(:)) ; imag(x(:))])];

function [ err ] = compute_rmse(X, Y, W, opts)

m = length(X);
Y_hat = cell(m,1);
for t=1:m
    if(opts.obj == 'R')
        Y_hat{t} = X{t} * W(:,t);
    else
        Y_hat{t} = sign(X{t} * W(:, t));
    end
end

if(opts.avg)
    all_errs = zeros(m,1);
    for t=1:m
        if(opts.obj == 'R')
            all_errs(t) = sqrt(mean((Y{t} - Y_hat{t}).^2));
        else
            all_errs(t) = mean(Y{t} ~= Y_hat{t});
        end
    end 
    err = mean(all_errs);
else

    end
end

