function [md, rowsort] = findminimaldist(A)
sv = size(A);
ilin=1:min(sv);
pm=perms(1:min(sv));
dold=intmax;
for ii=1:size(pm,1) %all n! configurarions
    index=sub2ind(size(A),pm(ii,:),ilin);
    d=sum(A(index));
    if d<dold
        dold=d;
        indmin=pm(ii,:);
        md=A(index);
    end
end

rowsort=indmin;

