    for i = 1:length(unif_idx_range)
       cur_weight = weights(unif_idx_range(i));
       F(i, indices{unif_idx_range(i)}) = 1/cur_weight;
    end
else
    c = C(:);
    c(c == 0) = eps*10;
    for i = 1:length(unif_idx_range)
       cur_indices = indices{unif_idx_range(i)};
       F(i,cur_indices) = c(cur_indices);
    end
