    ope_blur_1=padarray(ope_blur,[rows,cols],'circular','pre');
    ope_blur_1=ope_blur_1(xLen_flt_1+1:rows+xLen_flt_1,yLen_flt_1+1:cols+yLen_flt_1);

    rhslfft=lambda.*conj(fft2(ope_blur_1)).*fft2(f);

