    pos_idx_coo = [pos_idx pos_idx+max_idx pos_idx+max_idx*2];

    this.A_idx(idx_rec, 1:3) = pos_idx_coo(this.epoch(idx_rec), :);
    this.A_idx(idx_rec, 4:end) = this.A_idx(idx_rec, 4:end) + 3*(max_idx-o_max_idx);
end


