d     = size(G, 1); 
order = zeros(1, d); 
numbered    = false(1, d); 
order(1)    = initNode; 
numbered(initNode) = true; 
chordal = true;
C = cell(1,d);
numpa = zeros(1,d);
for i=2:d
  score = zeros(1,d);
  U = find(~numbered);% unnumbered verticies
  N = find(numbered); 
  assert(isequal(N, order(1:i-1)))
  for u=U
     score(u) = length(intersectPMTK(neighbors(G, u), N));
  end
  u = maxidx(score);
  order(i) = u;
  numbered(u) = true;

  pa = intersectPMTK(neighbors(G,u), order(1:i-1));
  if ~isequal(G(pa,pa), ones(length(pa)))
    chordal = false;
    return;
  end

  C{i} = [pa i];
  numpa(i) = length(pa);
end

isLadder = false(1,d);
for i=1:(d-1)
  isLadder(i) = numpa(i) >= numpa(i+1);
end
isLadder(d) = true;
cliques = C(isLadder);


end

