    for i=w+1:T,
        d1 = data(i-w:i-1, :);
        d2 = data(T-w+1:T, :);

        datacorr = corr(d1(:), d2(:));
        if (datacorr >= c),
            m=m+1;
            histdata(m, :) = data(i, :);
