    FreqVec,1/(fmin*(2^(kl/B)-1)),1,1,'spline');

CQcepstrum = dct(Ures_LogP_absCQT);

if strfind(ZsdD, 'Z'); scoeff = 1; else scoeff = 2; end
CQcepstrum_temp = CQcepstrum(scoeff:cf+1,:);
f_d = 3; % delta window size

