function [rocScore, result] = CrossValidationTest(data, labels, opts, num_fold)
nData = numel(labels);
posIds = find(labels==1);
negIds = find(labels==0);
rand_pos = randperm(numel(posIds));
rand_neg = randperm(numel(negIds));

num_pos_test = ceil(numel(posIds)/num_fold);
num_neg_test = ceil(numel(negIds)/num_fold);

all_id = 1 : nData;
test_ids = cell(num_fold, 1);
train_ids  = cell(num_fold, 1);
pred = zeros(nData, 1);
score = zeros(nData, 1);

for k = 1 : num_fold
    pos_test_ids = posIds(rand_pos(num_pos_test*(k-1)+1:min(end, num_pos_test*k)));
    neg_test_ids = negIds(rand_neg(num_neg_test*(k-1)+1:min(end, num_neg_test*k)));
    test_id = [pos_test_ids;neg_test_ids];
    train_id = setdiff(all_id, test_id);
    test_ids{k} = test_id;
    train_ids{k} = train_id;
    trainLabels = labels(train_id);
    testLabels = labels(test_id);
    trainData = data(train_id, :);
    testData = data(test_id, :);
    model = TrainModel(trainData, trainLabels, opts);
    pred(test_id) = TestModel(testData, testLabels, model);
    w = (model.sv_coef' * full(model.SVs));
    bias = -model.rho;
    score(test_id) = testData * w' + bias;
end

function hh = plotedges(node, edges, varargin)

edlen = size(edges, 1);
hh = [];
if (isempty(edges))
    return
end

rngstate = rand ('state');

if (size(edges, 1) == 1 || size(edges, 2) == 1) % a loop: single column/row edges
    randseed = hex2dec('623F9A9E'); % "U+623F U+9A9E"
    if (isoctavemesh)
        randseed = randseed + 3;
    end
    if (~isempty(getvarfrom({'caller', 'base'}, 'ISO2MESH_RANDSEED')))
        randseed = getvarfrom({'caller', 'base'}, 'ISO2MESH_RANDSEED');
    end
    rand('state', randseed);

    loops = edges(:)';
    if (~isnan(loops(end)))
        loops(end + 1) = nan;
    end
    seg = find(isnan(loops));
    seglen = length(seg);
    seghead = 1;
    for i = 1:seglen
        h = plotmesh(node(loops(seghead:seg(i) - 1), :), 'color', rand(3, 1), varargin{:});
        hh = [hh h];
        seghead = seg(i) + 1;
    end
else  % an edge list
    if (size(node, 2) == 2) % 2D polyline
        for i = 1:edlen
            h = line([node(edges(i, 1), 1) node(edges(i, 2), 1)], [node(edges(i, 1), 2) node(edges(i, 2), 2)], varargin{:});
            hh = [hh, h];
        end
    else  % 3D polyline
        for i = 1:edlen
            h = line([node(edges(i, 1), 1) node(edges(i, 2), 1)], [node(edges(i, 1), 2) ...
                                                                   node(edges(i, 2), 2)], [node(edges(i, 1), 3) node(edges(i, 2), 3)], varargin{:});
            hh = [hh, h];
        end
    end
end

