            repmat(talks_to(i,:),nan_count,1);
        j=j+nan_count;
    end

    L = (nn(:,1)<1)|(nn(:,1)>n)|(nn(:,2)<1)|(nn(:,2)>m);
    nn(L,:)=[];

    neighbors_list=[sub2ind([n,m],nn(:,1),nn(:,2)),nn];

    neighbors_list=unique(neighbors_list,'rows');

    neighbors_list=setdiff(neighbors_list,nan_list,'rows');

else
    neighbors_list=[];
end

