            x=sum(M,2)/l;                	%arithmetic mean
            M(M==0)=1;                      %enable geometric mean

end

function q = pathseg(l, m, maxc, p0)
    q0 = p0(:);
    switch m
        case 'S'
            f = @(t,q) [cos(q(3)), sin(q(3)), 0]';
        case 'L'
            f = @(t,q) [cos(q(3)), sin(q(3)), maxc]';
        case 'R'
            f = @(t,q) [cos(q(3)), sin(q(3)), -maxc]';
    end
    [t,q] = ode45(f, l, q0);
    q = q';  % points are column vectors
end



