    x = xy(1); y = xy(2);


    d = norm([x y]) * maxc;

    theta = mod2pi(atan2(y, x));
    alpha = mod2pi(-theta);
    beta = mod2pi(dth - theta);

    words = [];
    words = LSL(alpha, beta, d, 'LSL', words);

