  w=[];
  if length(grid_n)>1, w=grid_n; grid_n=[]; end
  if length(ramp_n)>1, w=ramp_n; ramp_n=[]; end
  if nargin < 6, window=w; end
  if isempty(window), window=hamming(n+1); end
  if ~isreal(window) || ischar(window), window=feval(window, n+1); end
