theta = [-2]; % BSL's prior volatility
phi = [-1;0]; % (log-) inverse-temperature, bias
N = 150; % number of trials
p = 0.75;
P = repmat([p,1-p,1-p,p],1,N); % probabilistic repetition of [1 0 0 1]
y = VBA_random ('Bernoulli', P(1 : N));

a = zeros(1,N);
gx = NaN(1,N);
x = zeros(dim.n,N);
