function output=iterate_C(C, epsilon)
[m,n]=size(C);
for i=1:n
    temp=C(:,i);
    norm_temp=norm(temp);
    if norm_temp>epsilon
        temp=temp-temp*epsilon/norm_temp;
    else
        temp=zeros(m,1);
    end
    output(:,i)=temp;
end
return;

