function [H2,Z2,sLen2,iter]=FGD_H(V,W,H,Z,Lpos,Lneg,tol)


n=size(H,2);
G=H.*(W'*(V./Z)+H*Lneg)./(sum(W)'*ones(1,n)+H*Lpos)-H;
L=Lpos-Lneg;
Z1=W*G;
a=sum(sum(L.*(G'*G)));
d=sum(sum(L.*(G'*H)))+sum(sum(Z1));
C=Z./Z1;

sLen=1;
for iter=1:20,
    [sum1,sum2]=SumC1(V,C,sLen);
    sLen1=sLen-(a*sLen-sum1+d)/(a+sum2);
    if abs(sLen1-sLen)<tol,
        break;
    else
        sLen=sLen1;
    end
end

if min(G(:))>=0
    sLen3=Inf;
else
    C=H./G;
    sLen3=min(-C(C<0));
end

