    mask = zeros(params.canonicalImageSize);
    mask = mask(:);
    mask(ind) = ob(ind);
    if ~isempty(ind)
        maskmax = max(mask);
        maskmin = min(mask);
        mask = (mask - maskmin)./(maskmax-maskmin);
        mm = reshape(mask,params.canonicalImageSize);
        mm2 = imdilate(mm,strel('ball',15,15));
        mm2max = max(mm2(:));
        mm2min = min(mm2(:));
        mm2n = (mm2 - mm2min)./(mm2max-mm2min);
         ind = find (mm2n>0);
         mm2n(ind) = mm2n(ind)+.5;
         subind = find (mm2n>1);
         mm2n(subind) = 1;
        mask = mm2n;
    end    
    M(:,fileIndex) = mask(:);
end

