function [ ihdr, endian, data_offset, user_data ] = read_sio_meta( filename )

fid = fopen(filename,'r','b');
ihdr = fread(fid,5,'*uint32');
fclose(fid);

switch ihdr(1)
    case hex2dec('FF017FFE') % Big endian, no user-data
        data_offset=20;
        endian='b';
        user_data=struct();
    case hex2dec('FE7F01FF') % Little endian, no user-data
        data_offset=20;
        endian='l';
        ihdr=swapbytes(ihdr);
        user_data=struct();
    case hex2dec('FF027FFD') % Big endian, with user-data
        endian='b';
        [user_data, user_data_length]=read_sio_userdata(filename,'b');
        data_offset=20+user_data_length;
    case hex2dec('FD7F02FF') % Little endian, with user-data
        endian='l';
        ihdr=swapbytes(ihdr);
        [user_data, user_data_length]=read_sio_userdata(filename,'l');
        data_offset=20+user_data_length;
    otherwise % Not an SIO file
        ihdr=[];
        endian=[];
        data_offset=0;
        user_data=struct([]);
end

end

function dist = compute_distance_matrix(X,x)


[D,N] = size(X);

try

    if(nargin>=2)
        [d,n] = size(x);
        if(D~=d)
            error('Both sets of vectors must have same dimensionality!\\n');
        end;
        X2 = sum(X.^2,1);
        x2 = sum(x.^2,1);
        if(exist('addchv')==3 & isreal(X))
            dist=addchv(X.'*x,-2,x2,X2);
        else
            dist = repmat(x2,N,1)+repmat(X2.',1,n)-2*X.'*x;
        end;

    else
        [D,N] = size(X);
        if(exist('addchv')==3 & isreal(X))
            X2 = sum(X.^2,1);
            dist=addchv(X.'*X,-2,X2,X2);
        else
            X2 = repmat(sum(X.^2,1),N,1);
            dist = X2+X2.'-2*X.'*X;
        end;
    end;
    dist = dist - diag(diag(dist));

