function [ppX, ppY] = getPixelsPerUnit()
    if ~isempty(pixPerX) && ~isempty(pixPerY)
        ppX = pixPerX;
        ppY = pixPerY;
    else
        [ppX, ppY] = getPixelsPerUnitForAxes(axHandle);
