        str_out_type = 'R_';
        mp_map = double(ant_mp.(sys_c).(trk).g_map);
    case 4 % Congruent cells gridding of size [stk_grid_step]
        str_type = 'congruent smoothed ';
        str_out_type = 'C_';
        mp_map = double(ant_mp.(sys_c).(trk).c_map);
