    fprintf('P(0) = %d\\n', p0)
    fprintf('P(1) = %d\\n', p1)
    q0 = f(p0);
    q1 = f(p1);
    while i <= N0
        p = p1-q1*(p1-p0)/(q1-q0);
        fprintf('P(%d) = %d\\n', i, p)
        if (abs(p-p1) < TOL)
            fprintf('\\n')
            return
        end
        i = i+1;
        p0=p1;
        q0=q1;
        p1=p;
        q1=f(p);
    end
    fprintf('Method failed after %d iterations\\n\\n', N0)
end

