function [ b, p1,p2 ] = fissurroundedby( s,p,c1,c2 )
p1=0;
p2=0;
notfound=1;
i=p-1;
while i>=1 && notfound
    if c1~=c2 
        if s(i)==c2
                break
        end
    end
    if s(i)==c1
        notfound=0;
        p1=i;
    end
    i=i-1;
end

notfound=1;
i=p+1;
while i<=length(s) && notfound
    if c1~=c2 
        if s(i)==c1
            break
        end
    end
    if s(i)==c2
        notfound=0;
        p2=i;
    end
    i=i+1;
end


if p1==0 || p2==0
    b=0; % not surrounded
else
    b=1;
end
end


