            if obj.is_below_target()
                xv = obj.increase();
            else
                xv = obj.decrease();
            end
            obj.x_values.append( xv );
        end

        function below = is_below_target( obj )
            below = obj.y < obj.y_target;
        end

        function xv = increase( obj )
            obj.lower = obj.x;
            if isinf( obj.upper )
                xv = obj.lower * 2;
            else
                xv = mean( [ obj.lower obj.upper ] );
            end
        end

        function xv = decrease( obj )
            obj.upper = obj.x;
            xv = mean( [ obj.lower obj.upper ] );
        end
    end

