json_str = strsplit( json_str, newline );
c = numel( json_str );
depth = 0;
tab = string( char( 9 ) );
for i = 2 : c - 1 % ignore first and last {} or []
    t = repmat( tab, [ 1 depth ] );
    s = json_str( i );
    json_str( i ) = strjoin( [ t s ], "" );
    if endsWith( s, [ "[" "{" ] )
        depth = depth + 1;
    elseif endsWith( s, [ "]" "}", "}," ] )
        depth = depth - 1;
    end
end
json_str = strjoin( json_str, newline );
