function [k, C] = DBSCAN(D, Eps, MinPts)
dLength = length(D);
O = zeros(dLength, 1);
C = cell(dLength);
d = zeros(dLength, dLength);

for i = 1:dLength
    for j = dLength:-1:i+1
        if abs(D(i)-D(j)) <= Eps
            d(i, j) = 1;
            d(j, i) = d(i, j);
        end
    end
    if sum(d(i, :)) >= MinPts
            O(i) = 1;
    end
end

k = 0;
Tau = ones(dLength, 1);
while sum(O) ~= 0
    Tau_old = Tau;
    j = 1;
    while O(j) == 0
        j = j+1;
    end
    Q = zeros(dLength, 1);
    Q(j) = 1;
    Tau(j) = 0;
    while sum(Q) ~= 0
        m = 1;
        while Q(m) == 0
            m = m+1;
        end
        Q(m) = 0;
        if sum(d(m,:)) >= MinPts
            for l = 1:dLength
                if d(m, l) == 1 && Tau(l) ~= 0
                    Q(l) = 1;
                    Tau(l) = 0;
                end
            end
        end
    end
    k = k+1;

    switch a
        case 1
            bw = 1; am = 0; fm = 0;
        case 2
            bw = 0; am = 1; fm = 0;
        case 3
            bw = 0; am = 0; fm = 1;
        case 4
            bw = 1; am = 1; fm = 1;
    end
end

end

