cub.mmCHOL = zeros(Np, Np, K); cub.mm = zeros(Np, Np, K);
for k=1:K
  cub.mm(:,:,k)     = cub.V'*diag(cub.J(:,k).*cub.W(:))*cub.V;
  cub.mmCHOL(:,:,k) = chol(cub.mm(:,:,k));
end

cub.w = cub.W; cub.W = cub.W*ones(1,K); cub.W = cub.W.*cub.J; 

cub.x = cub.V*x; cub.y = cub.V*y;
return

