function [ sceneA, sceneB ] = CutScene( scene, percentage, tolerance )


    r    = rand(1,4);
    rot  = RotationMat3D(r(1),[r(2),r(3),r(4)]);
    scene = TransformScene( scene, rot, [0;0;0] );

    rangeX = max(scene.feats.X) - min(scene.feats.X);
    rangeY = max(scene.feats.Y) - min(scene.feats.Y);
    rangeZ = max(scene.feats.Z) - min(scene.feats.Z);

    thrsX = min(scene.feats.X) : 0.1*rangeX : max(scene.feats.X);
    thrsY = min(scene.feats.Y) : 0.1*rangeY : max(scene.feats.Y);
    thrsZ = min(scene.feats.Z) : 0.1*rangeZ : max(scene.feats.Z);

    planeSign = round(rand);

    iC = 1;
    for iX = randsample(thrsX, numel(thrsX))
        for iY = randsample(thrsY, numel(thrsY))
            for iZ = randsample(thrsZ, numel(thrsZ))

                if planeSign
                    cut = mintersect(find(scene.feats.X < iX), find(scene.feats.Y < iY), find(scene.feats.Z < iZ));
                else
                    cut = mintersect(find(scene.feats.X > iX), find(scene.feats.Y > iY), find(scene.feats.Z > iZ));
                end

                cuts(iC,:) = [numel(cut), iX, iY, iZ];
                iC         = iC+1;

            end
        end
    end

    nPoints = numel(scene.feats.X);    
    idCut = find(cuts(:,1) > nPoints*(percentage-tolerance) & cuts(:,1) < nPoints*(percentage+tolerance));

    while isempty(idCut)

    end;



function [H,oldaxlims,errstr] = arrow_clicks(H,ud,x,y,z,ax,oldaxlims)
    errstr = '';
    if isempty(H)|isempty(ud)|isempty(x), return; end;
    needStart = all(isnan(ud(:,1:3)'))';
    needStop  = all(isnan(ud(:,4:6)'))';
    mask = any(needStart|needStop);
    if ~any(mask), return; end;
    ud(~mask,:)=[]; ax(:,~mask)=[];
    x(:,~mask)=[]; y(:,~mask)=[]; z(:,~mask)=[];
    set(H,'Visible','off');
    oldAx  = gca;
    limModes=get(ax(:),{'XLimMode','YLimMode','ZLimMode'});
    set(ax(:),{'XLimMode','YLimMode','ZLimMode'},{'manual','manual','manual'});
    jj = find(mask);
    for ii=1:length(jj),
        h = H(jj(ii));
        axes(ax(ii));
        if needStart(ii), prop='Start'; else, prop='Stop'; end;
        [wasInterrupted,errstr] = arrow_click(needStart(ii)&needStop(ii),h,prop,ax(ii));
        if wasInterrupted,
            delete(H(jj(ii:end)));
            H(jj(ii:end))=[];
            oldaxlims(jj(ii:end),:)=[];
            break;

function [Channel] = CreateSmallScaleFading( NoSources, ...
    NoDestinations, AntennaPerSource, AntennaPerDestination, dist)
if (nargin < nargin('CreateSmallScaleFading'))
    dist = {[]};
end
if (length(AntennaPerSource)>1)
    if (length(AntennaPerSource)<NoSources)
        disp('Error: Length of vector providing the number of anntennas per source is not enough');
        exit(0)
    end
else
    AntennaPerSource = repmat(AntennaPerSource,1,NoSources);
end
if (length(AntennaPerDestination)>1)
    if (length(AntennaPerDestination)<NoDestinations)
        disp('Error: Length of vector providing the number of anntennas per destination is not enough');
        exit(0)
    end
else
    AntennaPerDestination = repmat(AntennaPerDestination,1,NoDestinations);
end
for i = 1:1:NoSources
    for j=1:1:NoDestinations
        if (strcmp(dist{1},'Rice'))
            v = dist{2}*ones(AntennaPerSource(i),AntennaPerDestination(j));
            s = dist{3}*ones(AntennaPerSource(i),AntennaPerDestination(j));
            Channel(:,:,j,i) = sqrt(1/2)*(ricernd(v,s) + 1i*ricernd(v,s));
        else
            Channel(:,:,j,i) = sqrt(1/2)...
                *(randn(AntennaPerSource(i),AntennaPerDestination(j)) ...
                + 1i*randn(AntennaPerSource(i),AntennaPerDestination(j)));
        end
    end
end
end

