function circle = createCircle(varargin)


if nargin == 2
    p1 = varargin{1};
    p2 = varargin{2};
    x0 = p1(:,1);
    y0 = p1(:,2);
    r = hypot((p2(:,1)-x0), (p2(:,2)-y0));

elseif nargin == 3
    p1 = varargin{1};
    p2 = varargin{2};
    p3 = varargin{3};

    line1 = medianLine(p1, p2);
    line2 = medianLine(p1, p3);
    point = intersectLines(line1, line2);
    x0 = point(:, 1); 
    y0 = point(:, 2);

    r = hypot((p1(:,1)-x0), (p1(:,2)-y0));
end

