function D = DetailCurveCoeff(X,deep,is_real);

  R = SqueezeAngularFT(SeparateAngles(X,deep,is_real));

  for w=1:size(R,2)
    tmp = squeeze(R(2,w,:,:));
    R(2,w,:,:) = tmp([end,1:end-1], [end,1:end-1]);
  end
  for w=1:size(R,2)
    tmp = squeeze(R(4,w,:,:));
    R(4,w,:,:) = tmp([end,1:end-1], [end,1:end-1]);
  end

  nn = size(R);
  D = zeros(nn);
  for j = 1:size(R,1),
    for m = 1:size(R,2),
      W = squeeze(R(j,m,:,:));
      W = ifft2_mid0(W)*sqrt(prod(size(W)));
      D(j,m,:,:) = W;
    end
  end

  D = WENStoClockwise(D);

function [d] = lbfgsProd(g,S,Y,YS,lbfgs_start,lbfgs_end,Hdiag)

[nVars,maxCorrections] = size(S);
if lbfgs_start == 1
	ind = 1:lbfgs_end;
	nCor = lbfgs_end-lbfgs_start+1;
else
	ind = [lbfgs_start:maxCorrections 1:lbfgs_end];
	nCor = maxCorrections;
end
al = zeros(nCor,1);
be = zeros(nCor,1);

d = -g;
for j = 1:length(ind)
	i = ind(end-j+1);
	al(i) = (S(:,i)'*d)/YS(i);
	d = d-al(i)*Y(:,i);
end

d = Hdiag*d;

for i = ind
	be(i) = (Y(:,i)'*d)/YS(i);
	d = d + S(:,i)*(al(i)-be(i));
end

