    cvx_solver Mosek
    variable x(N,M)
    variable g(M)
    variable d(M)
    variable sum_x(N)
    variable sum_i(N)
    variable sum_j(M)
    variable Gamma(N) 
    variable lambda(M)
    variable v0(N,M) binary     
    variable v1(N) binary
    variable v2(M) binary

    variable sub_obj
    maximize sub_obj
    subject to 
        sub_obj == sum(sum_x);
        sum_x == sum(c.*x,2);
        sum_i == sum(x,2);
        sum_j == sum(x)';
        for i = 1:N
            for j = 1:M
                c(i,j) + Gamma(i) - lambda(j) >= 0;
                c(i,j) + Gamma(i) - lambda(j) <= bigM * v0(i,j);
                x(i,j) <= (1 - v0(i,j)) * bigM;
            end
        end

        for i = 1:N
            sum_i(i) <= z_mp(i);

