function numgrad = computeNumericalGradient_SR(image, label, weight_idx)
    global config mem;
    estimatedGrad = mem.grads;
    epsilon = config.NEW_MEM(0.01);
    numgrad = zeros(size(config.weights{1}{weight_idx}));

    for x = 1:size(config.weights{1}{weight_idx}, 1)
        for y = 1:size(config.weights{1}{weight_idx}, 2)
            config.weights{1}{weight_idx}(x, y) = config.weights{1}{weight_idx}(x, y) + epsilon;
            op_train_pipe(image, label);
            cost1 = config.cost;
            config.weights{1}{weight_idx}(x, y) = config.weights{1}{weight_idx}(x, y)  - (2*epsilon);
            op_train_pipe(image, label);
            cost2 = config.cost;
            config.weights{1}{weight_idx}(x, y) = config.weights{1}{weight_idx}(x, y) + epsilon;

            temp = (cost1 - cost2) / (2 * epsilon);
            numgrad(x, y) = gather(temp);

            diff = norm(temp-estimatedGrad{1}{weight_idx}(x, y));
            threshold = 10^-10;
                fprintf('numerical: %i, ', temp);
                fprintf('estimated: %i. \\n', estimatedGrad{1}{weight_idx}(x, y));
                fprintf('loop (%d, %d)\\n', x, y);
                fprintf('diff too large! diff: %i.\\n', diff);
        end
    end
end

function sigmoidBounds()

x = [-6:(1/10):6];

function sigupper = sigupper(eta,x)
  sigupper = exp(eta * x - fstar(eta));
end

function fstar = fstar(eta)
  fstar = -eta * log(eta) - (1-eta) * log(1-eta);
end

function sig = sigmoid(x)
  sig = exp(x) ./ (1 + exp(x));
end

function siglower = siglower(xi,x)
  siglower = sigmoid(xi) * exp((x-xi)/2 - lambda(xi)*(x.^2 - xi^2));
end

function lambda = lambda(xi)
  lambda = 1/(2*xi) * (sigmoid(xi) - 1/2);
end


function setEH(this, neff, osc, E_cell, H_cell, ge, grid3d)
	chkarg(istypesizeof(neff, 'complex'), '"neff" should be complex.');
	this.neff = neff;

	chkarg(istypesizeof(osc, 'Oscillation'), '"osc" should be instance of Oscillation.');
	this.osc = osc;

	chkarg(istypesizeof(grid3d, 'Grid3d'), '"grid3d" should be instance of Grid3d.');
	this.grid2d = Grid2d(grid3d, this.normal_axis);

	chkarg(istypesizeof(ge, 'GT'), '"ge" should be instance of GT.');

	Nh = this.grid2d.N(Dir.h);
	Nv = this.grid2d.N(Dir.v);
	h = this.grid2d.axis(Dir.h);
	v = this.grid2d.axis(Dir.v);

	assert(istypesizeof(E_cell, 'complexcell', [1 Axis.count], [Nh Nv]), ...
		'"E_cell" should be length-%d row cell array whose each element is %d-by-%d array with complex elements.', Axis.count, Nh, Nv);
	assert(istypesizeof(H_cell, 'complexcell', [1 Axis.count], [Nh Nv]), ...
		'"H_cell" should be length-%d row cell array whole each element is %d-by-%d array with complex elements.', Axis.count, Nh, Nv);

	if this.gt == ge  % source is J
		this.JMh = H_cell{v};
		this.JMv = -H_cell{h};
	else  % source is M
		this.JMh = E_cell{v};
		this.JMv = -E_cell{h};
	end

