function Actuators = Controller_PD(States,Control,Phase)


S = convert(States);   

C = Control.footOne;
pos = S.th1;    
vel = S.dth1;
A.T1 = C.Kp*(C.nomPos-pos) + C.Kd*(C.nomVel-vel);
if strcmp(Phase,'F') || strcmp(Phase,'S2')
    A.T1 = 0*A.T1;    %Can't use ankle torques in mid-air!
end

C = Control.footTwo;
pos = S.th2;    
vel = S.dth2;
A.T2 = C.Kp*(C.nomPos-pos) + C.Kd*(C.nomVel-vel);
if strcmp(Phase,'F') || strcmp(Phase,'S1')
    A.T2 = 0*A.T2;    %Can't use ankle torques in mid-air!
end

C = Control.legOne;
pos = S.L1;    
vel = S.dL1;
A.F1 = C.Kp*(C.nomPos-pos) + C.Kd*(C.nomVel-vel);

C = Control.legTwo;
pos = S.L2;    
vel = S.dL2;
A.F2 = C.Kp*(C.nomPos-pos) + C.Kd*(C.nomVel-vel);

C = Control.hip;
pos = S.th2 - S.th1;    
vel = S.dth2 - S.dth2;
A.Thip = C.Kp*(C.nomPos-pos) + C.Kd*(C.nomVel-vel);

start = sub2ind(size(as.occgrid), start(2), start(1));
as.openlist(1,1) = start;
as.t(start) = as.OPEN;

as.niter = 0; flag = 0;
while ~isempty(as.openlist)                              % L4
    queue = normc(as.openlist(2:size(as.openlist,1),:)');
    if as.algorithm == 2
        front = as.openlist(:,paretofront(queue));
        [~,col] = min(front(as.tie+1,:));
        X = front(1,col);                                % L5
    else
        [~,ind]=min(sum(queue,2));                       
        X = as.openlist(1,ind);                          % L5
    end
        as.DELETE(X);                                    % L6

    as.niter = as.niter + 1;
    if ~as.quiet && mod(as.niter, 20) == 0
        as.spinner();
    end

    for Y=as.neighbors(X)                                % L7,8
        if(Y==as.G)                                      % L9
            as.b(Y) = X; 
            as.updateCosts(Y,X,as.N)
            flag = 1;  % flag for goal
            break;
        end
        if as.t(Y)==as.NEW && as.costmap(Y)~=Inf
            as.b(Y) = X;
            as.updateCosts(Y,X,as.N);
            objspace = as.projectCost(Y,X);
            as.INSERT(Y, objspace, '');
        end
    end                
    if as.verbose
        disp(' ')
    end
    if flag==1 % goal found
        break;
    end

