function [node, elem] = meshcheckrepair(node, elem, opt, varargin)

extra = varargin2struct(varargin{:});

if (nargin < 3 || strcmp(opt, 'dupnode') || strcmp(opt, 'dup'))
    l1 = size(node, 1);
    [node, elem] = removedupnodes(node, elem, jsonopt('Tolerance', 0, extra));
    l2 = size(node, 1);
    if (l2 ~= l1)
        fprintf(1, '%d duplicated nodes were removed\\n', l1 - l2);
    end
end

if (nargin < 3 || strcmp(opt, 'duplicated') || strcmp(opt, 'dupelem') || strcmp(opt, 'dup'))
    l1 = size(elem, 1);
    elem = removedupelem(elem);
    l2 = length(elem);
    if (l2 ~= l1)
        fprintf(1, '%d duplicated elements were removed\\n', l1 - l2);
    end
end

if (nargin < 3 || strcmp(opt, 'isolated'))
    l1 = length(node);
    [node, elem] = removeisolatednode(node, elem);
    l2 = length(node);
    if (l2 ~= l1)
        fprintf(1, '%d isolated nodes were removed\\n', l1 - l2);
    end
end

if (nargin == 3 && strcmp(opt, 'open'))
    eg = surfedge(elem);
    if (~isempty(eg))
        error('open surface found, you need to enclose it by padding zeros around the volume');
    end
end

if (nargin < 3 || strcmp(opt, 'deep'))
    exesuff = getexeext;
    exesuff = fallbackexeext(exesuff, 'jmeshlib');
    deletemeshfile(mwpath('post_sclean.off'));
    saveoff(node(:, 1:3), elem(:, 1:3), mwpath('pre_sclean.off'));
    [status, output] = system([' "' mcpath('jmeshlib') exesuff '" "' mwpath('pre_sclean.off') '" "' mwpath('post_sclean.off') '"']);

function [mnv,mxv] = spm_minmax(g)



d   = [size(g) 1];
mxv = double(max(g(:)));
mnv = double(min(g(:)));
h   = zeros(256,1);
spm_progress_bar('Init',d(3),'Initial histogram','Planes loaded');
sw = warning('off','all');
for i=1:d(3)
    h = h + spm_hist(uint8(round(g(:,:,i)*(255/mxv))),ones(d(1)*d(2),1));
    spm_progress_bar('Set',i);
end;
warning(sw);
spm_progress_bar('Clear');

h(1)   = 0;
h(end) = 0;

[mn,v,mg] = fithisto((0:255)',h,1000,[1 128],[32 128].^2,[1 1]);
pr        = distribution(mn,v,mg,(0:255)');


mnd       = find((pr(:,1)./(sum(pr,2)+eps) < 0.5) & (0:255)' >mn(1));
if isempty(mnd) || mnd(1)==1 || mn(1)>mn(2),
    mnd = 1;
else
    mnd = mnd(1)-1;
end
mnv       = mnd*mxv/255;

ch  = cumsum(h(mnd:end))/sum(h(mnd:end));
ch  = find(ch>0.995)+mnd;
mxv = ch(1)/255*mxv;
return;
