    for i=1:nboots
        for j=1:nlambdas
            vars = find(selectedVars(j,:,i));
            W = zeros(dims+1,1);
            W([1,vars+1],1) = [ones(size(X,1),1),X(:,vars)]\\y;
            Wlsq{i,j} = W;
        end 
    end
end
