function [model, llh] = linRegEm(X, t, alpha, beta)
if nargin < 3
    alpha = 0.02;
    beta = 0.5;
end
[d,n] = size(X);
I = eye(d);
xbar = mean(X,2);
tbar = mean(t,2);

