function CPDpot = convert_dbn_CPDs_to_tables_slow(bnet, evidence)

obs_bitv = ~isemptycell(evidence(:));
[ss T] = size(evidence);
ns = bnet.node_sizes(:);

CPDpot = cell(ss,T); 

t = 1;
for n=1:ss
  ps = parents(bnet.dag, n);
  e = bnet.equiv_class(n, 1);
  if ~any(obs_bitv(ps))
    CPDpot{n,t} = convert_CPD_to_table_hidden_ps(bnet.CPD{e}, evidence{n,t});
  else
    CPDpot{n,t} = convert_to_table(bnet.CPD{e}, [ps n], evidence(:,1));
  end
end
for t=2:T
  for n=1:ss
    self = n+ss;
    ps = parents(bnet.dag, self);
    e = bnet.equiv_class(n, 2);
    if ~any(obs_bitv(ps))
      CPDpot{n,t} = convert_CPD_to_table_hidden_ps(bnet.CPD{e}, evidence{n,t});
    else
      CPDpot{n,t} = convert_to_table(bnet.CPD{e}, [ps self], evidence(:,t-1:t));
    end
  end
end

function [SPP] = point_to_hae(R_TGT_COA, Rdot_TGT_COA, ARP_COA, VARP_COA, SCP, HAE0, delta_HAE_MAX, NLIM)

iters = 0;
delta_HAE = Inf;

uGPN = wgs_84_norm(SCP);
LOOK = sign(sum(uGPN.'*cross(ARP_COA - repmat(SCP,1,size(ARP_COA,2)),VARP_COA,1),1));
GPP_LLH = ecf_to_geodetic(SCP);
GREF = bsxfun(@minus,SCP,bsxfun(@times,bsxfun(@minus, GPP_LLH(3,:), HAE0), uGPN));
while all(abs(delta_HAE) > delta_HAE_MAX) && (iters <= NLIM)
    GPP = point_to_ground_plane(R_TGT_COA, Rdot_TGT_COA, ARP_COA, VARP_COA, GREF, uGPN);
    uGPN = wgs_84_norm(GPP);
    GPP_LLH = ecf_to_geodetic(GPP);
    delta_HAE = GPP_LLH(3,:) - HAE0;
    GREF = GPP - repmat(delta_HAE,3,1) .* uGPN;
    iters = iters + 1;
end
SPN = repmat(LOOK,3,1).* cross(VARP_COA, (GPP - ARP_COA));
uSPN = SPN./repmat(sqrt(sum(SPN.^2)),3,1);
SF = sum(uGPN.*uSPN);
SLP = GPP - repmat(delta_HAE ./ SF,3,1) .* uSPN;
SPP_LLH = ecf_to_geodetic(SLP);
SPP_LLH(3,:) = HAE0;
SPP = geodetic_to_ecf(SPP_LLH);

end

function data_out = kpcaSimple(data_in,num_dim)

if num_dim > size(data_in,1)
    fprintf('\\nDimensions of output data has to be lesser than the dimensions of input data\\n');
    fprintf('Closing program\\n');
    return
end

K = zeros(size(data_in,2),size(data_in,2));
for row = 1:size(data_in,2)
    for col = 1:row
        temp = sum(((data_in(:,row) - data_in(:,col)).^2));
        K(row,col) = exp(-temp); % sigma = 1
    end
end
K = K + K'; 
for row = 1:size(data_in,2)
    K(row,row) = K(row,row)/2;
end
one_mat = ones(size(K))./size(data_in,2);
K_center = K - one_mat*K - K*one_mat + one_mat*K*one_mat;
clear K

opts.issym=1;                          
opts.disp = 0; 
opts.isreal = 1;
neigs = 30;
[eigvec eigval] = eigs(K_center,[],neigs,'lm',opts);
eig_val = eigval ~= 0;
eig_val = eig_val./size(data_in,2);
for col = 1:size(eigvec,2)
    eigvec(:,col) = eigvec(:,col)./(sqrt(eigval(col,col)));
end
[~, index] = sort(diag(eigval),'descend'); 
eigvec = eigvec(:,index);

data_out = zeros(num_dim,size(data_in,2));
for count = 1:num_dim
    data_out(count,:) = eigvec(:,count)'*K_center';
end

