  W = [Gds ones(size(Gds,1),1).*muGss]*iC(:,1:end-1); % [nDest x nSrc]
elseif (strcmpi(type,'slap'))
  W = Hds*iC(1:end-1,1:end-1); %(:,1:end-1); % [nDest x nSrc]
end
return;
