function transfo = createBasisTransform(source, target)


t1 = eye(3);
t2 = eye(3);

if nargin == 2
    t1(1:2, 1) = source(3:4);
    t1(1:2, 2) = source(5:6);
    t1(1:2, 3) = source(1:2);
else
    target = source;
end

t2(1:2, 1) = target(3:4);
t2(1:2, 2) = target(5:6);
t2(1:2, 3) = target(1:2);

transfo = zeros(3, 3);
maxSz = 1;
for i = 1:maxSz
    po = t1(1:2, 3, i)';
    px = po + t1(1:2, 1, i)';
    py = po + t1(1:2, 2, i)';

    t2i = inv(t2(:,:,i));
    pot = transformPoint(po, t2i);
    pxt = transformPoint(px, t2i);
    pyt = transformPoint(py, t2i);

    vx = pxt - pot;
    vy = pyt - pot;

    transfo(:,:,i) = [vx' vy' pot' ; 0 0 1];
end

