pde = struct('exactp',@exactp,'K',@K,'exactu',@exactu,'Dp',@gradp,...
             'f', @f,'g_D',@g_D,'g_N',@g_N);

    function s = K(pt)
       x = pt(:,1); y = pt(:,2);
       s(:,1) = 1 + 4*(x.^2 + y.^2);
       s(:,2) = 1 + 11*(x.^2 + y.^2);
    end
    function s = exactp(pt)
       x = pt(:,1); y = pt(:,2);
       s = x.^2 + y.^2;
    end
    function s = gradp(pt)
       x = pt(:,1); y = pt(:,2);
       s(:,2) = 2*y;
       s(:,1) = 2*x;       
    end
    function s = exactu(pt)
       Dp = gradp(pt);  % u = K*grad(p)
       K = K(pt);
       s(:,2) = K(:,2).*Dp(:,2);
       s(:,1) = K(:,1).*Dp(:,1);
    end
    function s = f(pt)
        x = pt(:,1); y = pt(:,2);
        s = 2+24*x.^2+16*y.^2++2+22*x.^2+66*y.^2;
        s = -s;
    end
    function s = g_D(pt)
       s = exactp(pt); 
    end
    function f = g_N(p,vargin)
        if nargin > 1
            f = dot(exactu(p),vargin,2);
        else
            f = zeros(size(p,1),1);

