case {'canon','scaled','sqrtscaled'}
  ht.U = h.U - z.U*(z.U'*h.U);
  ht.V = h.V - z.V*(z.V'*h.V);
case 'scaled1'
  [U S V] = svd(x.S); temp = 1./diag(S); IS2 = diag(temp.^2);
  D1 = U*IS2*U';
  D2 = V*IS2*V';
  ht.U = h.U - z.U*(D1*(z.U'*h.U));
  ht.V = h.V - z.V*(D2*(z.V'*h.V));
case 'sqrtscaled1'
  [U S V] = svd(x.S); temp = 1./diag(S); IS = diag(temp);
  D1 = U*IS*U';
  D2 = V*IS*V';
  ht.U = h.U - z.U*(D1*(z.U'*h.U));
  ht.V = h.V - z.V*(D2*(z.V'*h.V));
end

