function num_10_cycles = count_10_cycles_XII(H, cn)
num_10_cycles = 0;
M = size(H, 1);
for m1 = 1 : M - 4
    for i1 = 1 : cn(m1)
        index_1 = H(m1, i1);
        for m2 = m1 + 2 : M - 2
            for i2 = 1 : cn(m2)
                index_2 = H(m2, i2);
                if index_2 == index_1
                    for j1 = 1 : cn(m2)
                        index_3 = H(m2, j1);
                        if index_3 ~= index_2%horizontal comparison
                            for m3 = m2 + 2 : M
                                for i3 = 1 : cn(m3)
                                    index_4 = H(m3, i3);
                                    if index_4 == index_3
                                        for j2 = 1 : cn(m3)
                                            index_5 = H(m3, j2);
                                            if index_5 ~= index_4 && index_5 ~= index_2%horizontal comparison
                                                for m4 = m2 + 1 : m3 - 1
                                                    for i4 = 1 : cn(m4)
                                                        index_6 = H(m4, i4);
                                                        if index_6 == index_5
                                                            for j3 = 1 : cn(m4)
                                                                index_7 = H(m4, j3);
                                                                if index_7 ~= index_6 && index_7 ~= index_4 && index_7 ~= index_2%horizontal comparison
                                                                    for m5 = m1 + 1 : m2 - 1
                                                                        for i5 = 1 : cn(m5)
                                                                            index_8 = H(m5, i5);
                                                                            if index_8 == index_7
                                                                                for j4 = 1 : cn(m5)
                                                                                    index_9 = H(m5, j4);
                                                                                    if index_9 ~= index_8 && index_9 ~= index_3 && index_9 ~= index_5 && index_9 ~= index_2%horizontal comparison
                                                                                        for j5 = 1 : cn(m1)
                                                                                            index_10 = H(m1, j5);
                                                                                            if index_10 == index_9
                                                                                                num_10_cycles = num_10_cycles + 1;
                                                                                            end

function p = detectMonotoneSDPObjective(p)
p.monotoneobjectiveresponse = 0;
if any(p.c) && isempty(p.evalMap) && nnz(p.Q) == 0 && all(p.variabletype == 0)
    s = setdiff(find(p.c),[p.binary_variables p.integer_variables]);
    if ~isempty(s)
        ci = p.c(s);
        baseSign = sign(ci(1));
        if all(sign(ci) == baseSign)
            if nnz(p.F_struc(1:p.K.f,1 + s))==0
                if (baseSign == 1 && all(all(p.F_struc(p.K.f+1:p.K.f+p.K.l,1 + s)>=0))) || (baseSign == -1 && all(all(p.F_struc(p.K.f+1:p.K.f+p.K.l,1 + s)<=0)))
                    if all(all(p.F_struc(p.K.f+p.K.l+1:p.K.f+p.K.l+sum(p.K.q)+3*sum(p.K.e)+sum(p.K.p),1 + s)==0))
                        top = startofSDPCone(p.K);
                        working = 1;
                        for i = 1:length(p.K.s)
                            B = p.F_struc(top:top+p.K.s(i)^2-1,1+s);
                            working = working==1 && all(sum(B | B,1) <= 1) && ((all(all(B >= 0)) && baseSign == 1) || (all(all(B <= 0)) && baseSign == -1));
                            top = top + p.K.s(i)^2;
                        end
                        if working
                            p.monotoneobjectiveresponse = baseSign;
                        end
                    end
                end

    if suppress == -1
        if obj.elements.has_name('bus') && ...
                obj.elements.bus.nr > 500
            suppress = 1;
        else
            suppress = 0;
        end
    end

    s0 = cell2struct(num2cell(zeros(1,ne)), names, 2);
    s1 = cell2struct(num2cell(ones( 1,ne)), names, 2);
    s2 = struct('all', 1, 'any', 1);

    out = struct( ...
        'all', mpopt.out.all, ...
        'any', 0, ...
        'sec', struct( ...
            'cnt', s2, ...
            'sum', s2, ...
            'ext', s2, ...
            'det', struct( ...
                'all', -1, ...
                'any', 0, ...
                'elm', s1 ) ) );
    out.sec.cnt.all = out.all == 1 || (out.all == -1 && mpopt.out.sys_sum);
    out.sec.sum.all = out.sec.cnt.all;
    out.sec.ext.all = out.sec.cnt.all;
    out.sec.cnt.any = out.sec.cnt.all;
    out.sec.sum.any = out.sec.cnt.all;
    out.sec.ext.any = out.sec.cnt.all;

    for k = 1:ne
        out.sec.det.elm.(names{k}) = out.all == 1 || ...
            ( out.all == -1 && ~suppress && ...
                (~isfield(mpopt.out, names{k}) || mpopt.out.(names{k})) );
    end
    out.sec.det.any = any(cell2mat( ...
            cellfun(@double, struct2cell(out.sec.det.elm), ...
                    'UniformOutput', false) ));

    out.any = out.all == 1 || ...
                (out.all == -1 && (out.sec.cnt.all || out.sec.det.any ));

    if nargout > 1
        add = struct('s1', s1, 's0', s0, 'suppress', suppress, ...
            'names', {names}, 'ne', ne);
    end
end

